// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address owner = address(this);
        address user = address(0x1234);
        c.mintToken(user, 1000);
        vm.prank(owner);
        c.mintToken(owner, 100);

        bool ok;
        vm.prank(owner);
        try c.burn(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
